if __name__ == "__main__":
    here = os.path.dirname(os.path.abspath(__file__))
    for k, v in L.items(): assert len(v) == len(LANGS), (k, len(v))
    for k, (s, p) in LAYERS.items(): assert len(s) == len(LANGS) and len(p) == len(LANGS), k
    n = 0
    for i, lang in enumerate(LANGS):
        out = {k: v[i] for k, v in L.items()}
        for k, (s, p) in LAYERS.items(): out[f"layer.{k}"] = s[i]; out[f"layers.{k}"] = p[i]
        n = len(out)
        with open(os.path.join(here, f"labels.{lang}.json"), "w", encoding="utf-8") as fh:
            json.dump(out, fh, ensure_ascii=False, indent=1, sort_keys=True); fh.write("\n")
    print(f"{len(LANGS)} locales x {n} labels")
